package com.vit.archds.entity;
import jakarta.persistence.*; import java.time.Instant;
@Entity @Table(name="architecture_candidates",indexes=@Index(name="idx_candidates_job",columnList="job_id"))
public class ArchitectureCandidate { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="job_id") private AnalysisJob job; @Column(nullable=false,unique=true) private String candidateKey; @Column(nullable=false) private String name; @Column(nullable=false) private String style; @Column(length=6000) private String description; @Column(columnDefinition="TEXT") private String componentsJson; @Column(columnDefinition="TEXT") private String relationsJson; @Column(columnDefinition="TEXT") private String technologiesJson; @Column(columnDefinition="TEXT") private String advantagesJson; @Column(columnDefinition="TEXT") private String disadvantagesJson; @Column(columnDefinition="TEXT") private String assumptionsJson; @Column(columnDefinition="TEXT") private String risksJson; @Column(columnDefinition="TEXT") private String scoresJson; private Double weightedScore; private Boolean paretoOptimal=false; private Boolean verified=false; private Integer refinementIteration=0; @Column(columnDefinition="TEXT") private String plantUmlSource; @Column(columnDefinition="TEXT") private String diagramSvg; @Column(nullable=false,updatable=false) private Instant createdAt=Instant.now();
 public ArchitectureCandidate(){} public ArchitectureCandidate(AnalysisJob j,String k,String n,String s){job=j;candidateKey=k;name=n;style=s;} public Long getId(){return id;} public AnalysisJob getJob(){return job;} public String getCandidateKey(){return candidateKey;} public String getName(){return name;} public String getStyle(){return style;} public String getDescription(){return description;} public String getComponentsJson(){return componentsJson;} public String getRelationsJson(){return relationsJson;} public String getTechnologiesJson(){return technologiesJson;} public String getAdvantagesJson(){return advantagesJson;} public String getDisadvantagesJson(){return disadvantagesJson;} public String getAssumptionsJson(){return assumptionsJson;} public String getRisksJson(){return risksJson;} public String getScoresJson(){return scoresJson;} public Double getWeightedScore(){return weightedScore;} public Boolean getParetoOptimal(){return paretoOptimal;} public Boolean getVerified(){return verified;} public Integer getRefinementIteration(){return refinementIteration;} public String getPlantUmlSource(){return plantUmlSource;} public String getDiagramSvg(){return diagramSvg;} public void setDescription(String v){description=v;} public void setComponentsJson(String v){componentsJson=v;} public void setRelationsJson(String v){relationsJson=v;} public void setTechnologiesJson(String v){technologiesJson=v;} public void setAdvantagesJson(String v){advantagesJson=v;} public void setDisadvantagesJson(String v){disadvantagesJson=v;} public void setAssumptionsJson(String v){assumptionsJson=v;} public void setRisksJson(String v){risksJson=v;} public void setScoresJson(String v){scoresJson=v;} public void setWeightedScore(Double v){weightedScore=v;} public void setParetoOptimal(Boolean v){paretoOptimal=v;} public void setVerified(Boolean v){verified=v;} public void setRefinementIteration(Integer v){refinementIteration=v;} public void setPlantUmlSource(String v){plantUmlSource=v;} public void setDiagramSvg(String v){diagramSvg=v;}}
